INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('7bc07c73-e0c1-4238-9c5b-ff62fd6c0154', 'Common Area Maintenance Charges', '8', '9', 'PAGOS DE OTROS CONCEPTOS', 'No applicable information provided.', 'No aplica');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('7bc07c73-e0c1-4238-9c5b-ff62fd6c0154', 'Incremento de Renta', '5', '5', 'AJUSTE DE LA RENTA', E'- The Monthly Rent will increase every 12 months from the store''s opening date.\n- The increase is based on the change in the National Consumer Price Index (INPC).\n- The INPC is published monthly by the National Institute of Statistics and Geography (INEGI).\n- The comparison is made between the INPC two months before the lease starts or the last rent adjustment and the INPC two months before the new adjustment.\n- If the increase percentage is more than 4%, the maximum increase will be capped at 4%.', 'Las Partes convienen que la Renta Mensual será incrementada cada 12 (doce) meses, contado a partir de la fecha de apertura del local, se ajustará el importe de la Renta Mensual, incrementándose de acuerdo con la siguiente mecánica: Se tomará como base el porcentaje que haya variado el Índice Nacional de Precios al Consumidor (INPC), que publica mensualmente el instituto Nacional de Estadística y Geografía (INEGI), comparando el correspondiente al de dos meses inmediatos anteriores al mes de inicio del arrendamiento o al del último ajuste de renta y el correspondiente al de dos meses inmediatos anteriores al mes en que deba efectuarse el ajuste, en el entendido que si el porcentaje de incremento es mayor al 4% (cuatro por ciento) éste será el porcentaje máximo de incremento de la Renta Mensual.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('7bc07c73-e0c1-4238-9c5b-ff62fd6c0154', 'Late Fees', '14', '16', 'INTERESES MORATORIOS', E'- La tasa de interés por pagos atrasados es del 2% mensual.\n- Se aplica sobre el total de la deuda no pagada a tiempo.\n- Se cobra si el pago se retrasa más de 45 días desde la fecha de vencimiento.\n- El interés se calcula mensualmente o por fracción de mes mientras dure el retraso.\n- Se aplica desde la fecha en que debió hacerse el pago hasta que se liquide.', 'La tasa de intereses moratorios será del 2% (dos por ciento) mensual. Esta tasa se aplicará sobre el importe total del adeudo no cubierto puntualmente. Dicho interés moratorio será exigible cuando la Arrendataria se retrase en un pago por más de 45 (cuarenta y cinco) días de la fecha en que debió hacerlo. Este interés mensual se calculará cada mes o fracción de mes, mientras dure la mora, y por todo el tiempo transcurrido desde la fecha inicial en que debió hacerse el pago y hasta la liquidación del mismo.');
