 Lateral De López Mateos Sur","map_addr_2":"Subancla C","map_city_state_zip":"Guadalajara, Jalisco 44510","grid_brand":"Planet Fitness","location_created_at":"2025-10-06 14:27:50","active_lease_count_over_time":51325,"location_count_over_time":57975,"remaining_rent_liability_over_time":51325}'::jsonb);
