INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('0e23368f-8e77-45a1-a346-c0dae68e99e7', 'Fecha de Apertura', '31 de diciembre de 2024', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('0e23368f-8e77-45a1-a346-c0dae68e99e7', 'Common Area Maintenance Charges', '3', '4', 'CONTRAPRESTACIÓN', E'- The subtenant must pay a maintenance fee equal to 10% of the current monthly rent.\n- This fee starts when the business begins operations in the commercial area.\n- The fee will include the applicable value-added tax or any future tax that replaces it.', 'Adicionalmente EL SUBARRENDATARIO deberá cubrir una cuota de mantenimiento equivalente al 10% de la renta mensual actual vigente, dicha cantidad se comenzará a pagar a partir de la apertura o inicio-de- operaciones del negocio que operará en EL ÁREA COMERCIAL, En el entendido que a dicha cantidad se le agregará el correspondiente impuesto al valor agregado o el impuesto que en su momento llegare a sustituirlo.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('0e23368f-8e77-45a1-a346-c0dae68e99e7', 'Late Fees', '4', '4', 'CONTRAPRESTACIÓN', E'- If payment is late by more than 10 days, late interest will be added to the unpaid balance.\n- The late interest rate is three times the Interbank Equilibrium Interest Rate published by Banxico, spread over the time of delay.\n- If there are unpaid rents or interest, any payment made will first cover the interest, then the remaining amount will go towards the rent owed.\n- If rent is not paid within the first 10 days of the month, a 4% monthly late interest will be added, spread over the time of delay.\n- Payments will first cover interest, then any remaining amount will go towards the rent owed.', E'A partir del onceavo día se acumularán al saldo insoluto, intereses moratorios, calculados a razón de la tasa anualizada que resulte de multiplicar por 3 (tres) la TASA DE INTERES INTERBANCARIA DE EQUILIBRIO, publicada mensualmente por Banxico, prorrateado durante el tiempo que permanezca en mora; en caso de existir adeudos por rentas o intereses, EL SUBARRENDATARIO reconoce y acepta que cualquier cantidad que abonase se aplicará primero a cubrir los intereses, y en su caso, el restante a cuenta de las rentas adeudadas.\n\nEn caso de que EL SUBARRENDATARIO no realice el pago de la Renta dentro de los primeros diez días naturales del mes que corresponda, sobre el entendido que a partir del décimo primer día se acumularán al saldo insoluto, intereses moratorios, a razón del 4% (cuatro por ciento) mensual, prorrateado durante el tiempo que permanezca en mora; en caso de existir adeudos por rentas o intereses, EL SUBARRENDATARIO reconoce y acepta que cualquier cantidad que abonase se aplicará primero a cubrir los intereses, y en su caso, el restante a cuenta de las rentas adeudadas.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('0e23368f-8e77-45a1-a346-c0dae68e99e7', 'Incremento de Renta', '4', '5', 'AUMENTO DE RENTA', E'- La renta mensual se ajustará cada año el 1 de enero.\n- El ajuste se basa en el cambio del Índice Nacional de Precios al Consumidor publicado por el INEGI.\n- El cálculo del ajuste considera los 12 meses anteriores.\n- Si la renta no se actualiza antes del pago de enero, se pagará la renta del año anterior.\n- Cualquier diferencia por la actualización se pagará junto con la renta de febrero y se reflejará en la factura.', E'Las Partes convienen que la renta mensual se actualizará y ajustará cada año calendario, durante la vigencia del presente Contrato, durante el primer día del mes de enero, de conformidad con lo previsto en el párrafo siguiente. Las actualizaciones se calcularán por 12 (doce) meses calendario, Contados a partir del próximo 01 de enero del 2026.\n\nLa renta mensual variará en el mismo porcentaje en que hubiere variado el Índice Nacional de Precios al Consumidor que publique el INEGI en el Diario Oficial de la Federación (o el índice que lo sustituyere para medir la inflación en los Estados Unidos Mexicanos) durante los 12 (doce) meses anteriores.\n\nEn caso de que, la renta mensual no se actualice previo al día de pago del mes de enero EL SUBARRENDATARIO pagará la renta mensual aplicable el año anterior y el faltante derivado de la actualización, en su caso, se pagará a LA SUBARRENDADORA renta mensual junto con la renta mensual del mes de febrero, dicho complemento de renta se verá reflejado en la factura correspondiente');
