el Local. Esta cantidad se entregará a la Arrendadora a la firma del presente Contrato en su domicilio o en cualquiera de las modalidades estipuladas en la Cláusula Segunda del presente instrumento.', NULL, false, '{"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1}'::jsonb);
