INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('3938998f-4355-4ad3-8919-f8f47caa1afe', 'Common Area Maintenance Charges', '9', '10 A)', 'GASTOS DE ADMINISTRACIÓN Y MANTENIMIENTO', E'- The Tenant must pay the Landlord an additional 5% of the Monthly Rent plus VAT for administration and maintenance costs.\n- This payment is calculated based on the current rent amount at the time the payment is due.\n- The Tenant cannot request an account of how these funds are used or influence the management or maintenance decisions of the Shopping Center.\n- The Landlord is required to use these funds to maintain, repair, and replace parts of the Shopping Center to keep it in good working condition.', 'La Arrendataria se obliga a cubrir a la Arrendadora por concepto de gastos de administración y mantenimiento una cantidad equivalente al 5% (cinco por ciento), del importe de la Renta Mensual más el impuesto al valor agregado. Cada pago mensual por este concepto será calculado sobre el importe de la renta vigente a la fecha en que sea exigible dicho pago. La Arrendataria acepta expresamente que no tendrá derecho a exigir rendición de cuentas respecto a las cantidades que pague por dichos conceptos, ni podrá intervenir para determinar el tipo o las características de la administración o mantenimiento del Centro Comercial, sin embargo, la Arrendadora tendrá la obligación de usar los fondos para mantener, reparar y reemplazar el Centro Comercial y los elementos del mismo para mantenerlos en óptimas condiciones de funcionamiento.');
